//! `papers.latexenc`: LaTeX and unicode, with the tables of that module
//! (generated by `tools/gen_latexenc.py`).
//!
//! [`string_to_latex`] is what `fix --encoding latex` writes; [`latex_to_unicode`] is
//! what papers uses to compare names and file names. The decoding of the
//! values of an entry (`--encoding unicode`, `add`) is that of pylatexenc,
//! not of this module.

use std::collections::HashMap;
use std::sync::OnceLock;

use unicode_normalization::UnicodeNormalization;
use unicode_normalization::char::canonical_combining_class;

use super::latexenc_tables::{
    UNICODE_TO_CRAPPY_LATEX1, UNICODE_TO_CRAPPY_LATEX2, UNICODE_TO_LATEX,
};

fn latex_map() -> &'static HashMap<char, &'static str> {
    static MAP: OnceLock<HashMap<char, &'static str>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut map = HashMap::new();
        for (k, v) in UNICODE_TO_LATEX {
            let mut chars = k.chars();
            if let (Some(c), None) = (chars.next(), chars.next()) {
                map.insert(c, *v);
            }
        }
        map
    })
}

/// A string as LaTeX: each character by the table, but the spaces and braces (`string_to_latex`).
pub fn string_to_latex(string: &str) -> String {
    let map = latex_map();
    let mut out = String::with_capacity(string.len());
    for c in string.chars() {
        match c {
            ' ' | '{' | '}' => out.push(c),
            c => match map.get(&c) {
                Some(latex) => out.push_str(latex),
                None => out.push(c),
            },
        }
    }
    out
}

/// A LaTeX string as unicode, by the table (`latex_to_unicode`): the accents
/// are put after their letter, the result is normalized (NFC) and the braces that are left are removed.
pub fn latex_to_unicode(string: &str) -> String {
    let mut string = string.to_string();
    if string.contains('\\') || string.contains('{') {
        for (k, v) in UNICODE_TO_CRAPPY_LATEX1
            .iter()
            .chain(UNICODE_TO_LATEX.iter())
        {
            if string.contains(v) {
                string = string.replace(v, k);
            }
        }
    }

    // if there are still very crappy items
    if string.contains('\\') {
        for (k, v) in UNICODE_TO_CRAPPY_LATEX2 {
            if string.contains(v) {
                let mut parts: Vec<String> = string.split(v).map(str::to_string).collect();
                for key in 0..parts.len() {
                    if key + 1 < parts.len() && !parts[key + 1].is_empty() {
                        // change order to display accents
                        let c = parts[key + 1].chars().next().unwrap();
                        parts[key].push(c);
                        parts[key + 1].drain(..c.len_utf8());
                    }
                }
                string = parts.join(k);
            }
        }
    }

    // LaTeX has the accents before the character, unicode after it: swap them
    let chars: Vec<char> = string.chars().collect();
    let mut cleaned = String::with_capacity(string.len());
    let mut i = 0;
    while i < chars.len() {
        if canonical_combining_class(chars[i]) == 0 {
            cleaned.push(chars[i]);
            i += 1;
        } else if i + 1 < chars.len() {
            cleaned.push(chars[i + 1]);
            cleaned.push(chars[i]);
            i += 2;
        } else {
            // a trailing combining character is discarded
            i += 1;
        }
    }

    let cleaned: String = cleaned.nfc().collect();
    cleaned.replace(['{', '}'], "")
}

/// Protect the capitals of a title: `Hello` as `{H}ello` (`protect_uppercase`).
pub fn protect_uppercase(string: &str) -> String {
    // re.sub('([^{]|^)([A-Z])([^}]|$)', r'\g<1>{\g<2>}\g<3>', string)
    let c: Vec<char> = string.chars().collect();
    let n = c.len();
    let matched = |p: usize| -> Option<(String, char, String, usize)> {
        let upper = |i: usize| i < n && c[i].is_ascii_uppercase();
        let g3 = |r: usize| -> Option<(String, usize)> {
            if r < n && c[r] != '}' {
                Some((c[r].to_string(), r + 1))
            } else if r == n {
                Some((String::new(), r))
            } else {
                None
            }
        };
        // `[^{]`, then `^`
        if p < n
            && c[p] != '{'
            && upper(p + 1)
            && let Some((g, end)) = g3(p + 2)
        {
            return Some((c[p].to_string(), c[p + 1], g, end));
        }
        if p == 0
            && upper(0)
            && let Some((g, end)) = g3(1)
        {
            return Some((String::new(), c[0], g, end));
        }
        None
    };
    let mut out = String::new();
    let mut i = 0;
    while i < n {
        match matched(i) {
            Some((g1, g2, g3, end)) => {
                out.push_str(&g1);
                out.push('{');
                out.push(g2);
                out.push('}');
                out.push_str(&g3);
                i = end;
            }
            None => {
                out.push(c[i]);
                i += 1;
            }
        }
    }
    out
}
